{
  "name": "Tony Hawk Pro Skater Skate Park",
  "version": "1.0",
  "design_for": "2-minute trick run",
  "target_skater": "Professional",

  "geometry": {
    "total_area": {
      "width": 50,
      "length": 40,
      "height": 12
    },
    "surfaces": {
      "riding_surface": {
        "material": "polyurethane-coated_concrete",
        "roughness": 0.8,
        "friction_coefficient": 0.6
      },
      "safety_areas": {
        "padding_thickness": 0.3,
        "padding_material": "foam"
      }
    }
  },

  "key_features": [
    {
      "name": "Entrance_Rail",
      "type": "horizontal_bar",
      "position": {"x": 5, "y": 1, "z": 5},
      "dimensions": {"length": 20, "diameter": 0.1},
      "description": "Starting trick area - push-ups and slides"
    },
    {
      "name": "Vertical_Ramp",
      "type": "vertical_wall",
      "position": {"x": 25, "y": 6, "z": 20},
      "dimensions": {"width": 15, "height": 12, "depth": 5},
      "features": ["K-gap", "flatbar_approach"],
      "description": "Main air trick element"
    },
    {
      "name": "Half_Pipe",
      "type": "pool",
      "position": {"x": 40, "y": 0, "z": 35},
      "dimensions": {"radius": 8, "height": 6},
      "description": "Manual and flow tricks"
    },
    {
      "name": "Flatbar_Complex",
      "type": "rail_system",
      "position": {"x": 10, "y": 2, "z": 40},
      "dimensions": {"length": 25, "diameter": 0.15},
      "features": ["boulderslide_cap", "triple_crossover"],
      "description": "Technical trick section"
    }
  ],

  "trick_sequence": {
    "total_duration": 120,
    "phases": [
      {
        "name": "Warmup",
        "duration": 30,
        "difficulty": "Easy",
        "location": "entrance_rail"
      },
      {
        "name": "Main_Sequence",
        "duration": 60,
        "difficulty": "Expert",
        "locations": ["vertical_ramp", "half_pipe", "flatbar_complex"]
      },
      {
        "name": "Finale",
        "duration": 30,
        "difficulty": "Medium",
        "location": "vertical_ramp"
      }
    ]
  },

  "skater_requirements": {
    "deck_size": {"width": 8, "length": 32},
    "max_height": 6,
    "trick_types": [" Ollie", "Air", "Flip", "Grab", "Manual", "Slide"],
    "difficulty_range": ["Beginner", "Intermediate", "Expert"]
  },

  "rendering_spec": {
    "style": "photorealistic_tony_hawk",
    "lighting": "daytime_cinematic",
    "camera": "dynamic_skater_eye",
    "texture_quality": "high_poly",
    "animation_style": "fluid_1950s_physics"
  }
}

// Tony Hawk Skate Park 3D Generator
// This script generates 3D geometry for the Tony Hawk skate park
define(`TonyHawkSkateParkGenerator, {
  init() {
    this.materials = {
      ridingSurface: new THREE.MeshPhongMaterial({
        color: 0x404040,
        shininess: 10,
        roughness: 0.8
      }),
      rails: new THREE.MeshPhongMaterial({
        color: 0x606060,
        shininess: 30
      }),
      concrete: new THREE.MeshPhongMaterial({
        color: 0x505050,
        shininess: 5
      })
    };

    this.createPark();
  },

  createPark() {
    this.group = new THREE.Group();

    // Main riding surface
    this.createRidingSurface();

    // Entrance rail
    this.createEntranceRail();

    // Vertical ramp
    this.createVerticalRamp();

    // Half pipe
    this.createHalfPipe();

    // Flatbar complex
    this.createFlatbarComplex();

    return this.group;
  },

  createRidingSurface() {
    const geometry = new THREE.BoxGeometry(50, 1, 40);
    const surface = new THREE.Mesh(geometry, this.materials.ridingSurface);
    surface.position.set(0, 0, 0);
    this.group.add(surface);
  },

  createEntranceRail() {
    const railGeometry = new THREE.BoxGeometry(20, 0.1, 0.5);
    const rail = new THREE.Mesh(railGeometry, this.materials.rails);
    rail.position.set(0, 1, 5);
    this.group.add(rail);
  },

  createVerticalRamp() {
    // Vertical wall
    const wallGeometry = new THREE.BoxGeometry(15, 12, 5);
    const wall = new THREE.Mesh(wallGeometry, this.materials.concrete);
    wall.position.set(25, 6, 20);
    this.group.add(wall);

    // K-gap cut-out
    const gapGeometry = new THREE.BoxGeometry(1, 2, 1);
    const gap = new THREE.Mesh(gapGeometry, this.materials.ridingSurface);
    gap.position.set(25 + 7.5, 3, 22.5);
    this.group.add(gap);
  },

  createHalfPipe() {
    const curvePoints = [];
    for (let i = 0; i <= 32; i++) {
      const angle = (i * Math.PI) / 32;
      curvePoints.push(new THREE.Vector3(
        Math.cos(angle) * 8,
        0,
        Math.sin(angle) * 8
      ));
    }

    const curve = new THREE.CatmullRomCurve3(curvePoints);
    const tubeGeometry = new THREE.TubeGeometry(
      curve, 32, 6, 8, false
    );

    const tube = new THREE.Mesh(tubeGeometry, this.materials.ridingSurface);
    tube.position.set(40, 0, 35);
    tube.rotation.y = Math.PI / 2;
    this.group.add(tube);
  },

  createFlatbarComplex() {
    const railGeometry = new THREE.BoxGeometry(25, 0.15, 0.8);
    const flatbar = new THREE.Mesh(railGeometry, this.materials.rails);
    flatbar.position.set(10, 2, 40);
    this.group.add(flatbar);
  }
});

// Export for use in HTML
if (typeof module !== 'undefined' && module.exports) {
  module.exports = TonyHawkSkateParkGenerator;
}
